   ```c
   int open_file(const char *filename) {
       FILE *file = fopen(filename, "r");
       if (file == NULL) {
           fprintf(stderr, "Failed to open file: %s\n", filename);
           return ERROR_FILE_NOT_FOUND;
       }
       // Proceed with file operations
       fclose(file);
       return SUCCESS;
   }
   ```

4. **Check Return Values:**
   Always check the return values of functions that can fail. For example:
   ```c
   int allocate_memory(size_t size) {
       void *ptr = malloc(size);
       if (ptr == NULL) {
           fprintf(stderr, "Memory allocation failed\n");
           return ERROR_OUT_OF_MEMORY;
       }
       // Use the allocated memory
       free(ptr);
       return SUCCESS;
   }
   ```

5. **Use `setjmp` and `longjmp` for Complex Error Handling:**
   For more complex error handling, especially in nested function calls, use `setjmp` and `longjmp`:
   ```c
   #include <setjmp.h>

   jmp_buf env;

   void some_function() {
       if (setjmp(env) == 0) {
